class Book:
    def __init__(self, title):
        self.title = title
    def __str__(self):
        return f"Book({self.title})"
    def __repr__(self):
        return f"Book(title={self.title!r})"

b = Book("Python")
print(str(b))
print(repr(b))
print(b)

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __eq__(self, other):
        return (self.x, self.y) == (other.x, other.y)

p1 = Point(1, 2)
p2 = Point(1, 2)
print(p1 == p2)
print(Point.__hash__)
print(p1.__hash__ is None)

class User:
    def __init__(self, uid):
        self.uid = uid
    def __eq__(self, other):
        return isinstance(other, User) and self.uid == other.uid
    def __hash__(self):
        return hash(self.uid)

u1 = User(7)
u2 = User(7)
print(u1 == u2)
print(hash(u1) == hash(u2))
d = {u1: "admin"}
print(d[u2])

class Box:
    def __init__(self, items):
        self.items = items
    def __len__(self):
        return len(self.items)
    def __bool__(self):
        return len(self.items) > 0

empty = Box([])
full = Box(["a", "b"])
print(len(empty), len(full))
print(bool(empty), bool(full))

class Playlist:
    def __init__(self, songs):
        self.songs = songs
    def __getitem__(self, index):
        return self.songs[index]

p = Playlist(["a", "b", "c", "d"])
print(p[0])
print(p[-1])
print(p[1:3])

class Team:
    def __init__(self, members):
        self.members = members
    def __contains__(self, name):
        return name in self.members

t = Team(["Alice", "Bob"])
print("Bob" in t)
print("Cara" in t)

class Adder:
    def __init__(self, base):
        self.base = base
    def __call__(self, x):
        return self.base + x

add5 = Adder(5)
print(add5(3))
print(callable(add5))

