class Tracked:
    def __init__(self):
        self.value = 10
    def __getattribute__(self, name):
        print(f"access: {name}")
        return object.__getattribute__(self, name)
    def __getattr__(self, name):
        return "fallback"

t = Tracked()
print(t.value)
print(t.other)

class Vector:
    def __init__(self, x):
        self.x = x
    def __add__(self, other):
        return Vector(self.x + other.x)
    def __radd__(self, other):
        return Vector(other + self.x)
    def __repr__(self):
        return f"Vector({self.x})"

print(Vector(1) + Vector(2))
print(2 + Vector(3))

class Counter:
    def __init__(self, n):
        self.n = n
    def __iadd__(self, other):
        self.n += other
        return self
    def __repr__(self):
        return f"Counter({self.n})"

c = Counter(1)
alias = c
c += 5
print(c)
print(alias is c)

from functools import total_ordering

@total_ordering
class Version:
    def __init__(self, major, minor):
        self.major = major
        self.minor = minor
    def __eq__(self, other):
        return (self.major, self.minor) == (other.major, other.minor)
    def __lt__(self, other):
        return (self.major, self.minor) < (other.major, other.minor)

v1 = Version(1, 2)
v2 = Version(2, 0)
print(v1 < v2)
print(v1 <= v2)
print(v1 > v2)
print(v2 >= v1)

class Countdown:
    def __init__(self, start):
        self.start = start
    def __iter__(self):
        n = self.start
        while n > 0:
            yield n
            n -= 1

for x in Countdown(3):
    print(x)
